private typealias Row = List<Any?>
private class Table(val name:String, val columns:List<Column>, val key:Int) {
    var rows = emptyList<Row>();
    fun column(n:String) = columns.indexOfFirst {
        it.name == n
    }
}
private data class Entry(val name:String, val table:Table, val offset:Int)
private class Scope {
    val entries = mutableListOf<Entry>();
    var width = 0
    fun add(n:String, t:Table) {
        if (entries.any {
            it.name == n
        }) fail("duplicate table name $n");
        entries.add(Entry(n, t, width));
        width += t.columns.size
    }
    fun resolve(e:Expr):String {
        val found = mutableListOf<Pair<Int, String>>();
        var seen = false;
        for (p in entries) if (e.table == null || e.table == p.name) {
            seen = true;
            val i = p.table.column(e.column);
            if (i >= 0) found.add(p.offset+i to p.table.columns[i].type)
        };
        if (e.table != null && !seen) fail("unknown table ${e.table}");
        if (found.isEmpty()) fail("unknown column ${e.text}");
        if (found.size>1) fail("ambiguous column ${e.column}");
        e.index = found[0].first;
        return found[0].second
    }
}
private fun compatible(a:String, b:String) = a == b || a == "NULL" || b == "NULL"
private fun requireType(a:String, b:String, op:String) {
    if (!compatible(a, b)) fail("type mismatch for $op")
}
private fun check(e:Expr, s:Scope, allow:Boolean = false, grouped:List<Int>? = null, inside:Boolean = false):String {
    if (e.kind == "literal") return if (e.value == null)"NULL" else if (e.value is Long)"INT" else "TEXT";
    if (e.kind == "ref") {
        val t = s.resolve(e);
        if (grouped != null && !inside && e.index !in grouped) fail("column ${e.text} is not grouped");
        return t
    }
    if (e.kind == "aggregate") {
        if (!allow || inside) fail("misuse of aggregate ${e.op}");
private fun condition(e:Expr?, s:Scope, name:String, allow:Boolean = false, grouped:List<Int>? = null) {
    if (e != null) requireType(check(e, s, allow, grouped), "INT", name)
}
private fun truth(v:Any?) = v != null && (v as Long) != 0L
private fun evaluate(e:Expr, row:Row, group:List<Row>? = null):Any? {
    if (e.kind == "literal") return e.value;
    if (e.kind == "ref") return row[e.index];
private fun satisfies(e:Expr?, r:Row, g:List<Row>? = null) = e == null || truth(evaluate(e, r, g))
private fun countRows(n:Int) = "$n ${if(n==1)"row" else "rows"}"
private fun written(v:Any?) = v?.toString() ?: "NULL"
private class Database {
    val tables = mutableMapOf<String, Table>()
    fun table(n:String) = tables[n] ?: fail("unknown table $n")
    fun targets(t:Table, names:List<String>):List<Int> {
        val a = mutableListOf<Int>();
        for (n in names) {
            val i = t.column(n);
            if (i<0) fail("unknown column $n");
            if (i in a) fail("duplicate column $n");
            a.add(i)
        };
        return a
    }
    fun constraints(t:Table, rows:List<Row>, checked:List<Int>) {
        for (i in checked) {
